style.css:
/* 簡化背景顏色設置 */
body, html {
  background-color: #000000 !important; /* 黑色背景 */
  color: #ffffff !important; /* 一般文字設為白色 */
}

/* 設置未點擊的連結為淺藍色 (#9FFFFF) */
a {
  color: #9FFFFF !important; /* 淺藍色 */
  text-decoration: none; /* 預設無底線 */
}

/* 設置已點擊的連結為亮紫色 */
a:visited {
  color: #dda0dd !important; /* 亮紫色 */
  text-decoration: none; /* 預設無底線 */
}

/* 當滑鼠懸停於連結時，顯示底線 */
a:hover {
  text-decoration: underline;
}
